{
  "primary_meaning": "Jesus Christ as the sacrificial Lamb of God whose death atones for sin",
  "primary_basis": [
    "John 1:29, 36 (Lamb of God who takes away the sin of the world)",
    "Revelation 5:6-12; 7:14; 12:11; 13:8 (the slain yet victorious Lamb)",
    "1 Corinthians 5:7 (Christ our Passover lamb)",
    "1 Peter 1:18-19 (redeemed by the precious blood of Christ, a lamb without blemish)",
    "Isaiah 53:7 (suffering servant led like a lamb to the slaughter, read christologically)",
    "Exodus 12 (Passover lamb as typological background)"
  ],
  "alternatives": [
    {
      "meaning": "General symbol of innocence, meekness, or gentleness (sometimes applied to believers or as a moral quality rather than specifically to Christ's atonement)",
      "basis": [
        "Isaiah 11:6; 65:25 (peaceable kingdom imagery)",
        "Luke 10:3; Matthew 10:16 (disciples sent as lambs among wolves)",
        "Broader pastoral and prophetic lamb imagery"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The Passover or temple sacrificial lamb understood primarily in its original Israelite cultic sense, without necessary reference to Jesus",
      "basis": [
        "Exodus 12",
        "Leviticus sacrificial regulations",
        "Historical-critical readings that stop at OT cult"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Apocalyptic or messianic conqueror figure emphasizing victory and judgment more than (or instead of) substitutionary sacrifice",
      "basis": [
        "Revelation's Lamb who opens seals, wages war, and rules (e.g., Rev 6; 17:14)"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Literal animal or non-christological metaphor with no fixed doctrinal load",
      "basis": [
        "Ordinary pastoral references in OT narrative and poetry"
      ],
      "prominence": "rare"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "In mainstream historic Christian teaching and biblical interpretation, 'the Lamb' (especially capitalized or in titular use) overwhelmingly denotes Jesus Christ in his atoning, paschal role, integrating OT sacrifice typology with NT fulfillment texts. Alternative emphases exist but rarely displace this core identification in confessional or standard exegetical literature."
}
